import{_ as l,a0 as p,w as o,s as c,ao as d,I as n,x as i,a1 as t,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何在 Ubuntu 22.04 上安裝 CRI-O 容器運行時 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 22.04 上安裝 CRI-O 容器運行時 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 22.04 上安裝 CRI-O 容器運行時 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 22.04 上安裝 CRI-O 容器運行時 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20230321.0 ⭐️⭐️ How to Install CRI-O (Container Runtime) on Ubuntu 22.04","title":"如何在 Ubuntu 22.04 上安裝 CRI-O 容器運行時","tag":"202304","desc":""},"relativePath":"202304/20230321.0 ⭐️⭐️ How to Install CRI-O (Container Runtime) on Ubuntu 22.04.md","filePath":"[post].md"}'),r={name:"202304/20230321.0 ⭐️⭐️ How to Install CRI-O (Container Runtime) on Ubuntu 22.04.md"};function h(u,s,g,b,k,C){const a=p("Link");return o(),c("div",null,[s[15]||(s[15]=d(`<h1 id="如何在-ubuntu-22-04-上安裝-cri-o-容器運行時" tabindex="-1">如何在 Ubuntu 22.04 上安裝 CRI-O 容器運行時 <a class="header-anchor" href="#如何在-ubuntu-22-04-上安裝-cri-o-容器運行時" aria-label="Permalink to “如何在 Ubuntu 22.04 上安裝 CRI-O 容器運行時”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202304/03/105419akd0pr3ns2n50nz0.jpg" alt=""></p><p>CRI-O 是 Kubernetes 的開源輕量級容器運行時。它是使用 <ruby>開放容器組織<rt>Open Container Initiative</rt></ruby>（OCI）兼容運行時的 Kubernetes <ruby>容器運行時接口<rt>Container Runtime Interface</rt></ruby>（CRI）的實現。在運行 Kubernetes 時，它是 Docker 的完美替代品。</p><p>在本指南中，我們將逐步演示如何在 Ubuntu 22.04 LTS 上安裝 CRI-O。</p><h3 id="先決條件" tabindex="-1">先決條件 <a class="header-anchor" href="#先決條件" aria-label="Permalink to “先決條件”">​</a></h3><p>在開始之前，這是你需要的：</p><ul><li>具有 SSH 訪問權限的 Ubuntu 22.04 實例</li><li>在實例上配置的 sudo 用户</li><li>快速穩定的互聯網連接</li></ul><p>有了這個，讓我們開始吧。</p><h3 id="步驟-1-更新系統並安裝依賴" tabindex="-1">步驟 1：更新系統並安裝依賴 <a class="header-anchor" href="#步驟-1-更新系統並安裝依賴" aria-label="Permalink to “步驟 1：更新系統並安裝依賴”">​</a></h3><p>立即登錄你的服務器實例，並按如下方式更新包列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span></code></pre></div><p>更新本地包索引後，按如下方式安裝依賴項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install apt-transport-https ca-certificates curl gnupg2 software-properties-common -y</span></span></code></pre></div><h3 id="步驟-2-添加-cri-o-存儲庫" tabindex="-1">步驟 2：添加 CRI-O 存儲庫 <a class="header-anchor" href="#步驟-2-添加-cri-o-存儲庫" aria-label="Permalink to “步驟 2：添加 CRI-O 存儲庫”">​</a></h3><p>要安裝 CRI-O，我們需要在 Ubuntu 上添加或啓用它的倉庫。但首先，你需要根據操作系統和要安裝的 CRI-O 版本定義變量。</p><p>因此，定義如下變量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ export OS=xUbuntu_22.04</span></span>
<span class="line"><span>$ export CRIO_VERSION=1.24</span></span></code></pre></div><p>完成後，運行以下命令集以添加 CRI-O Kubic 倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;deb https://download.opensuse.org/repositories/devel:/kubic:/libcontainers:/stable/$OS/ /&quot;| sudo tee /etc/apt/sources.list.d/devel:kubic:libcontainers:stable.list</span></span>
<span class="line"><span>$ echo &quot;deb http://download.opensuse.org/repositories/devel:/kubic:/libcontainers:/stable:/cri-o:/$CRIO_VERSION/$OS/ /&quot;|sudo tee /etc/apt/sources.list.d/devel:kubic:libcontainers:stable:cri-o:$CRIO_VERSION.list</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Set-Crio-Repository-Ubuntu-Linux.png" alt=""></p><p>此後，為 CRI-O 倉庫導入 GPG 密鑰：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -L https://download.opensuse.org/repositories/devel:kubic:libcontainers:stable:cri-o:$CRIO_VERSION/$OS/Release.key | sudo apt-key add -</span></span>
<span class="line"><span>$ curl -L https://download.opensuse.org/repositories/devel:/kubic:/libcontainers:/stable/$OS/Release.key | sudo apt-key add -</span></span></code></pre></div><p>這會產生如下輸出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Import-GPG-Keys-for-Crio-Repository-Ubuntu-Linux.png" alt=""></p><p>再次更新包索引，使系統與新添加的 CRI-O Kubic 倉庫同步：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span></code></pre></div><h3 id="步驟-3-在-ubuntu-22-04-上安裝-cri-o" tabindex="-1">步驟 3：在 Ubuntu 22.04 上安裝 CRI-O <a class="header-anchor" href="#步驟-3-在-ubuntu-22-04-上安裝-cri-o" aria-label="Permalink to “步驟 3：在 Ubuntu 22.04 上安裝 CRI-O”">​</a></h3><p>添加倉庫後，使用 APT 包管理器安裝 CRI-O 和運行時客户端：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install cri-o cri-o-runc -y</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Apt-Install-Crio-Ubuntu-Linux.png" alt=""></p><p>安裝後，啓動並啓用 CRI-O 守護程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl start crio</span></span>
<span class="line"><span>$ sudo systemctl enable crio</span></span></code></pre></div><p>接下來，驗證 CRI-O 服務是否正在運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status crio</span></span></code></pre></div><p>你應該看到以下輸出，表明 CRI-O 服務正在按預期運行：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Start-Enable-Crio-Service-Ubuntu.png" alt=""></p><h3 id="步驟-4-為-cri-o-安裝-cni-插件" tabindex="-1">步驟 4：為 CRI-O 安裝 CNI 插件 <a class="header-anchor" href="#步驟-4-為-cri-o-安裝-cni-插件" aria-label="Permalink to “步驟 4：為 CRI-O 安裝 CNI 插件”">​</a></h3><p>接下來，你需要安裝 CNI（<ruby>容器網絡接口<rt>Container Network Interface</rt></ruby>）以及 CNI 插件。請記住，環回和橋接配置已啓用並且足以使用 CRI-O 運行 <ruby>容器莢<rt>Pod</rt></ruby>：</p><p>因此，要安裝 CNI 插件，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install containernetworking-plugins -y</span></span></code></pre></div><p>安裝後，編輯 CRI-O 配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nano /etc/crio/crio.conf</span></span></code></pre></div><p>取消註釋 <code>network_dir</code> 和 <code>plugin_dirs</code> 部分，並在 <code>plugin_dirs</code> 下添加 <code>/usr/lib/cni/</code>。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Crio-Conf-Network-Plugins-Directory-Ubuntu.png" alt=""></p><p>保存更改並退出配置文件。</p><p>接下來，重啓 CRIO 服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart crio</span></span></code></pre></div><h3 id="步驟-5-安裝-cri-o-工具" tabindex="-1">步驟 5：安裝 CRI-O 工具 <a class="header-anchor" href="#步驟-5-安裝-cri-o-工具" aria-label="Permalink to “步驟 5：安裝 CRI-O 工具”">​</a></h3><p>此外，你還需要安裝 <code>cri-tools</code> 包，它提供了 <code>crictl</code> 命令列程序，用於交互和管理容器和 pod。</p><p>為此，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install -y cri-tools</span></span></code></pre></div><p>安裝後，確認 <code>crictl</code> 的版本和 <code>RunTimeVersion</code> 如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo crictl --runtime-endpoint unix:///var/run/crio/crio.sock version</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Crictl-Crio-Version-Check-Ubuntu-Linux.png" alt=""></p><p>一定要檢查 CRI-O 是否準備好使用以下命令部署容器莢：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo crictl info</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Crictl-Info-Command-Ubuntu.png" alt=""></p><p><code>crictl</code> 命令提供自動補全功能，讓你可以通過按 <code>TAB</code> 鍵自動補全命令。要啓用命令補全，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo su -</span></span>
<span class="line"><span></span></span>
<span class="line"><span># crictl completion &gt; /etc/bash_completion.d/crictl</span></span></code></pre></div><p>然後重新加載當前的 Bash 會話：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># source ~/.bashrc</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Enable-Bash-Completion-Crictl-Command-Ubuntu.png" alt=""></p><p>要使用自動補全功能，你需要註銷或啓動新的終端會話。然後只需鍵入 <code>crictl</code> 命令並按 <code>TAB</code> 鍵即可查看所有選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ crictl</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Crictl-Command-Options-Ubuntu.png" alt=""></p><h3 id="步驟-6-使用-crictl-程序創建容器莢" tabindex="-1">步驟 6：使用 crictl 程序創建容器莢 <a class="header-anchor" href="#步驟-6-使用-crictl-程序創建容器莢" aria-label="Permalink to “步驟 6：使用 crictl 程序創建容器莢”">​</a></h3><p>至此，CRI-O 已完全安裝和配置並準備好啓動容器莢。在本節中，我們將在容器莢中創建一個 Apache Web 服務器並確認它是否正在處理請求。</p><p>首先，我們將使用容器莢配置文件設置一個沙箱或隔離環境，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nano apache_sandbox.json</span></span></code></pre></div><p>然後我們將以下配置添加到文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;metadata&quot;: {</span></span>
<span class="line"><span>        &quot;name&quot;: &quot;apache-sandbox&quot;,</span></span>
<span class="line"><span>        &quot;namespace&quot;: &quot;default&quot;,</span></span>
<span class="line"><span>        &quot;attempt&quot;: 1,</span></span>
<span class="line"><span>        &quot;uid&quot;: &quot;hdishd83djaidwnduwk28bcsb&quot;</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    &quot;linux&quot;: {</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    &quot;log_directory&quot;: &quot;/tmp&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>保存並退出。接下來使用以下命令創建容器莢。這會打印出很長的字母數字，它是容器莢 ID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo crictl runp apache_sandbox.json</span></span></code></pre></div><p>要確認容器莢已創建，請運行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo crictl pods</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Crictl-Pods-Status-Ubuntu.png" alt=""></p><p>要檢索有關創建的容器莢的更多信息，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo crictl inspectp --output table 05ba2f0704f22</span></span></code></pre></div><p>這將打印出 ID、名稱、UID、命名空間、創建日期、內部 IP 等詳細信息。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Crictl-Inspect-Pod-Ubuntu-Linux.png" alt=""></p><h3 id="步驟-7-在容器莢中創建容器" tabindex="-1">步驟 7：在容器莢中創建容器 <a class="header-anchor" href="#步驟-7-在容器莢中創建容器" aria-label="Permalink to “步驟 7：在容器莢中創建容器”">​</a></h3><p>這部分中，我們將在容器莢中創建一個 Apache Web 服務器容器。因此，使用 <code>crictl</code> 程序從 Docker Hub 拉取 Apache Web 服務器鏡像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo crictl pull httpd</span></span></code></pre></div><p>你可以如圖所示驗證拉取的鏡像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo crictl images</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Crictl-pull-image-ubuntu.png" alt=""></p><p>接下來，我們將為 Apache Web 服務器定義一個容器配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nano container_apache.json</span></span></code></pre></div><p>複製並粘貼以下代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;metadata&quot;: {</span></span>
<span class="line"><span>      &quot;name&quot;: &quot;apache&quot;</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>  &quot;image&quot;:{</span></span>
<span class="line"><span>      &quot;image&quot;: &quot;httpd&quot;</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>  &quot;log_path&quot;:&quot;apache.0.log&quot;,</span></span>
<span class="line"><span>  &quot;linux&quot;: {</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>保存並退出配置文件。</p><p>最後，要將容器連接到之前創建的沙盒容器莢，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo crictl create 05ba2f0704f22 container_apache.json apache_sandbox.json</span></span></code></pre></div><p>這會向終端輸出一長串字母數字 ID。請記下此 ID。</p><p>最後，使用 ID 啓動 Apache Web 服務器容器，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo crictl start 37f4d26510965452aa918f04d629f5332a1cd398d4912298c796942e22f964a7</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Create-Container-Inside-Pod-Ubuntu-Linux.png" alt=""></p><p>要檢查容器狀態，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo crictl ps</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Pods-Status-Crictl-Command-Ubuntu.png" alt=""></p><p>要驗證 Apache Web 服務器是否正在運行，請使用 <code>curl</code> 命令和容器莢的內部 ID 向 Web 服務器發送 HTTP 請求：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -I 10.85.0.2</span></span></code></pre></div><p>以下輸出確認 Web 服務器正在運行：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Curl-Command-Httpd-Pod-Ubuntu.png" alt=""></p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>這就是全部的指南。我們已經在 Ubuntu 22.04 上成功安裝了 CRI-O，並繼續創建容器莢和容器。歡迎你提出意見和反饋。</p><hr>`,107)),n("p",null,[s[1]||(s[1]=i("via: ",-1)),t(a,{href:"https://www.linuxtechi.com/install-crio-container-runtime-on-ubuntu/"},{default:e(()=>[...s[0]||(s[0]=[i("https://www.linuxtechi.com/install-crio-container-runtime-on-ubuntu/",-1)])]),_:1})]),n("p",null,[s[6]||(s[6]=i("作者：",-1)),t(a,{href:"https://www.linuxtechi.com/author/james/"},{default:e(()=>[...s[2]||(s[2]=[i("James Kiarie",-1)])]),_:1}),s[7]||(s[7]=i(" 選題：",-1)),t(a,{href:"https://github.com/lkxed/"},{default:e(()=>[...s[3]||(s[3]=[i("lkxed",-1)])]),_:1}),s[8]||(s[8]=i(" 譯者：",-1)),t(a,{href:"https://github.com/geekpi"},{default:e(()=>[...s[4]||(s[4]=[i("geekpi",-1)])]),_:1}),s[9]||(s[9]=i(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=i("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:e(()=>[...s[11]||(s[11]=[i("Linux中國",-1)])]),_:1}),s[14]||(s[14]=i(" 榮譽推出",-1))])])}const x=l(r,[["render",h]]);export{y as __pageData,x as default};
